-- The demo database as a script. bin/demo.sqlite is build output and not in
-- version control: the server writes it on first start, in CreateDemoDatabase
-- and CreateBulkDemoTables, and THAT code is the source of truth. This file is
-- the same state written out - to read in a diff, and to restore from:
--   sqlite3 demo.sqlite < demo.sql
-- Shaped like templates.sql: created only if missing, emptied before it is
-- filled, rows ordered by ID. Re-applying it is repeatable. Nothing reads it at
-- startup, and it is regenerated by hand when the seeding code changes.

-- the table every sample query starts from
create table if not exists Customer (
  ID integer primary key autoincrement,
  Name text not null,
  City text not null);
delete from Customer;

-- the currency and date columns TDtoInvoiceRow writes into
create table if not exists Invoice (
  ID integer primary key autoincrement,
  CustomerID integer not null,
  Amount real not null,
  InvoiceDate text not null);
delete from Invoice;

-- a hundred rows, so a result set is worth looking at
create table if not exists Mitarbeiter (
  ID integer primary key autoincrement,
  Name text not null,
  Abteilung text not null,
  Eintritt text not null,
  Gehalt real not null);
delete from Mitarbeiter;

-- what AddTDtoProjektRow writes into - no DTO in WriteDtos names it
create table if not exists Projekt (
  ID integer primary key autoincrement,
  Titel text not null,
  CustomerID integer not null,
  Start text not null,
  Budget real not null);
delete from Projekt;

-- joined against Projekt by GetStundenProProjekt
create table if not exists Zeitbuchung (
  ID integer primary key autoincrement,
  MitarbeiterID integer not null,
  ProjektID integer not null,
  Datum text not null,
  Stunden real not null);
delete from Zeitbuchung;

-- ArtNr is the natural key: what KeyField is for, hence the index below
create table if not exists Artikel (
  ID integer primary key autoincrement,
  ArtNr integer not null,
  ArtName text not null,
  Kind text);
delete from Artikel;

-- the natural key really is one: without this an update matching on ArtNr
-- could change more than the row it meant
create unique index if not exists Artikel_ArtNr_unique on Artikel(ArtNr);

-- what the Rules column is demonstrated on: a postcode and an e-mail address
-- are shapes no column type states, so AddKontakt states them - '2:plz;3:email'
create table if not exists Kontakt (
  ID integer primary key autoincrement,
  Name text not null,
  Plz text not null,
  Email text not null);
delete from Kontakt;
